const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const array=v=>Array.isArray(v)?v:[];
const text=v=>typeof v==='string'?v:v?.text||v?.statement||v?.summary||'';
const time=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(v))+' KST':'아직 확인 전';
const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v:v?time(v):'미확인';
const url=id=>'/catalyst?thesis='+encodeURIComponent(id);
const safeUrl=v=>{try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}};
const link=(href,label)=>safeUrl(href)?`<a href="${esc(safeUrl(href))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
const positions={HOLDING:'보유 중',WATCHING:'관심만 있음',UNSPECIFIED:'보유 여부 미입력'};
const states={STRENGTHENED:'지지하는 새 근거',WEAKENED:'약화하는 새 근거',MIXED:'엇갈린 근거',NO_MATERIAL_CHANGE:'중요한 변화 없음',INSUFFICIENT_DATA:'자료 부족'};
const scopes={COMPLETE_WITHIN_SCOPE:'요청 범위 확인',PARTIAL:'일부 자료만 확인',SOURCE_UNAVAILABLE:'자료 접근 실패',BUDGET_LIMITED:'이용 한도로 일부 확인',FAILED:'검토 실패'};
const changes={NEW_EVENT:'새 사건',NEWLY_DISCOVERED_OLD_INFORMATION:'이번에 추가 확인한 과거 정보',CORRECTION:'정정된 자료',REPEATED_COVERAGE:'이미 확인한 사건',DATA_REFRESH:'자료 갱신',INITIAL_BASELINE:'처음 확보한 기준 자료'};
const active=r=>['queued','running','QUEUED','RUNNING'].includes(r?.status);
const headers=()=>({'Content-Type':'application/json',...(sessionStorage.getItem('catalyst-admin-token')?{Authorization:'Bearer '+sessionStorage.getItem('catalyst-admin-token')}:{})});
function client(signal){return async(path='',options={})=>{const r=await fetch('/api/theses'+path,{...options,headers:headers(),signal});const body=await r.json();if(!r.ok)throw Object.assign(Error(body.message||'투자 생각을 불러오지 못했습니다. 다시 시도해 주세요.'),{code:body.code});return body;};}
function sourcesMarkup(sources=[]){return array(sources).length?`<details class="thesis-sources"><summary>출처와 자료 기준 ${sources.length}개</summary><ol>${sources.map(s=>`<li><strong>${esc(s.id||'')} ${link(s.url,s.title||s.publisher||'근거 자료')}</strong>${s.quote?`<blockquote>${esc(s.quote)}</blockquote>`:''}<small>발행 ${esc(date(s.publishedAt||s.published_at))} · 자료 확인 ${esc(date(s.retrievedAt||s.observedAt||s.retrieved_at))}</small>${s.period||s.fiscalPeriod?`<small>대상 기간 ${esc(s.fiscalPeriod||(typeof s.period==='string'?s.period:s.period.label))}</small>`:''}${/^\/reports\?report=-?\d+%3A\d+$/.test(s.reportPath||'')?`<a href="${esc(s.reportPath)}" data-nav>리포트 보기 →</a>`:''}</li>`).join('')}</ol></details>`:'';}
function listMarkup(title,items){return array(items).length?`<section class="thesis-evidence-group"><h3>${title}</h3><ul>${items.map(x=>`<li>${esc(text(x))}${array(x.refs||x.sourceIds).length?` <small>근거 ${esc((x.refs||x.sourceIds).join(', '))}</small>`:''}</li>`).join('')}</ul></section>`:'';}
function changeMarkup(c){return `<article class="thesis-change"><span class="thesis-badge">${esc(changes[c.kind||c.changeType||c.type]||'확인한 자료')}</span>${({supports:'지지 근거',weakens:'약화 근거',mixed:'엇갈린 근거',neutral:'참고 자료'})[c.direction]?`<span class="thesis-scope">${esc(({supports:'지지 근거',weakens:'약화 근거',mixed:'엇갈린 근거',neutral:'참고 자료'})[c.direction])}</span>`:''}<h3>${esc(c.title||c.premise||c.premiseStatement||'생각과 연결된 변화')}</h3><dl>${c.before||c.previous||c.previousBaseline?`<div><dt>이전 기준</dt><dd>${esc(text(c.before||c.previous||c.previousBaseline))}</dd></div>`:''}<div><dt>확인한 사실</dt><dd>${esc(text(c.after||c.newFact||c.fact||c.current||c.summary))}</dd></div>${c.significance||c.meaning||c.interpretation?`<div><dt>AI 해석</dt><dd>${esc(text(c.significance||c.meaning||c.interpretation))}</dd></div>`:''}</dl>${c.uncertainty?`<p class="thesis-muted">추가 확인 · ${esc(c.uncertainty)}</p>`:''}${array(c.sourceIds||c.refs).length?`<small>근거 ${esc((c.sourceIds||c.refs).join(', '))}</small>`:''}${c.publishedAt||c.eventTime?`<small>사건 ${esc(date(c.eventTime))} · 발행 ${esc(date(c.publishedAt))}</small>`:''}</article>`;}
export function thesisReviewMarkup(review){
 if(!review)return '<div class="thesis-empty"><h3>아직 변화 확인 전</h3><p>새 변화 확인을 누르면 저장한 생각과 자료를 비교합니다.</p></div>';
 if(active(review))return '<p class="thesis-progress" role="status">저장한 생각에 필요한 자료를 비교하고 있습니다. 이 화면을 나가도 검토 기록은 유지됩니다.</p>';
 const r=review.result||review,scope=r.investigationStatus||review.investigationStatus||r.scopeStatus||r.completionStatus||r.researchStatus||r.coverageStatus;
 const findings=array(r.changes),summary=r.summary||r.conclusion||r.answer||array(r.blocks)[0]?.text,remainingBlocks=array(r.blocks).slice(1);
 return `<section class="thesis-review"><header><div><span class="thesis-badge">${esc(states[r.assessment||r.outcome||r.status]||'자료 확인 결과')}</span>${scope?`<span class="thesis-scope">${esc(scopes[scope]||'조사 범위 확인 필요')}</span>`:''}<h2>무엇이 달라졌나요?</h2></div></header>${summary?`<p class="thesis-conclusion">${esc(text(summary))}</p>${array(r.blocks?.[0]?.refs).length?`<small>근거 ${esc(r.blocks[0].refs.join(', '))}</small>`:''}`:'<p>검토를 완료하지 못했습니다. 자료 확보 상태를 확인한 뒤 다시 실행할 수 있습니다.</p>'}<p class="thesis-muted">생각 버전 ${esc(review.thesisVersion||review.version||'미확인')} · 검토 ${esc(time(review.completedAt||r.reviewedAt||review.updatedAt))}${r.baselineAt?`<br>비교 기준 ${esc(time(r.baselineAt))}`:''}</p>${remainingBlocks.length?`<div class="thesis-analysis-blocks">${remainingBlocks.map(b=>`<section><small>${esc(({fact:'자료에서 확인',calculation:'계산',analysis:'AI 해석',assumption:'가정',unknown:'추가 확인'})[b.kind]||'분석')}</small><p>${esc(b.text)}</p>${array(b.refs).length?`<small>근거 ${esc(b.refs.join(', '))}</small>`:''}</section>`).join('')}</div>`:''}${findings.slice(0,3).map(changeMarkup).join('')}${findings.length>3?`<details><summary>나머지 변화 ${findings.length-3}개</summary>${findings.slice(3).map(changeMarkup).join('')}</details>`:''}<div class="thesis-evidence-grid">${listMarkup('생각을 지지하는 근거',r.supportingEvidence||r.supporting)}${listMarkup('반대 근거·다른 설명',r.opposingEvidence||r.counterEvidence||r.opposing)}${listMarkup('아직 확인하지 못한 부분',r.unknowns||r.dataGaps)}${listMarkup('다음에 확인할 것',r.nextChecks||r.nextSteps)}</div>${r.coverageNote?`<p class="thesis-muted">확인 범위 · ${esc(r.coverageNote)}</p>`:''}${sourcesMarkup(r.sources)}</section>`;
}
export function thesisCardMarkup(item,{home=false}={}){
 const review=item.latestReview,result=review?.result||review,assessment=result?.assessment||result?.outcome||result?.status;
 const priorVersion=review&&item.currentVersion&&review.thesisVersion!==item.currentVersion;
 const label=priorVersion?'현재 생각은 아직 변화 확인 전':active(review)?'변화 확인 중':review?states[assessment]||'검토 결과 확인':'아직 변화 확인 전';
 const assets=array(item.linkedAssets).map(a=>a.name||a.symbol),tags=[...assets,...array(item.linkedIndustryConcepts)];
 return `<article class="surface thesis-card"><div class="thesis-card-meta"><span class="thesis-badge">${esc(label)}</span>${item.status==='ARCHIVED'?'<span>보관됨</span>':''}</div><h${home?'3':'2'}><a href="${url(item.id)}" data-nav>${esc(item.title)}</a></h${home?'3':'2'}><p class="thesis-muted">${esc(tags.join(' · ')||'산업·경제 생각')} · ${esc(positions[item.positionContext]||positions.UNSPECIFIED)}</p><p class="thesis-card-summary">${priorVersion?'이전 버전 검토 · ':''}${esc(text(result?.summary||result?.conclusion||array(result?.blocks)[0]?.text)||'저장한 생각을 기준으로 새로운 근거를 비교해 보세요.')}</p><small>최근 검토 ${esc(time(item.lastReviewAt||review?.completedAt))}</small><div class="thesis-actions"><a href="${url(item.id)}" data-nav>자세히 보기 →</a>${item.status!=='ARCHIVED'?`<button type="button" class="secondary-button" data-thesis-review="${esc(item.id)}" data-thesis-version="${esc(item.currentVersion)}" ${active(review)?'disabled':''}>${active(review)?'확인 중…':'새 변화 확인'}</button>`:''}</div></article>`;
}
export function thesisEditMarkup(draft,editing){
 return `<section class="surface thesis-editor"><h1>${editing?'내 생각 수정':'추적할 생각 확인'}</h1><p class="thesis-muted">${editing?'수정하면 새 버전으로 저장됩니다. 이전 생각과 검토 기록은 남습니다.':'AI 답변에서 정리한 초안입니다. 내 생각에 맞게 수정하고, 연결할 종목을 직접 선택해 주세요.'}</p><form data-thesis-form><label>제목<input name="title" maxlength="120" value="${esc(draft.title)}" required></label><label>내가 보고 있는 생각<textarea name="thesisText" maxlength="4000" rows="5" required>${esc(draft.thesisText)}</textarea></label><fieldset class="thesis-assets"><legend>연결 종목 <small>선택하지 않아도 저장할 수 있습니다</small></legend><div data-thesis-selected></div><label>종목 검색<input type="search" data-thesis-asset-search placeholder="종목명 또는 티커" autocomplete="off"></label><div data-thesis-asset-options></div></fieldset><div class="thesis-form-grid"><label>보유·관심 구분<select name="positionContext">${Object.entries(positions).map(([key,label])=>`<option value="${key}" ${draft.positionContext===key||!draft.positionContext&&key==='UNSPECIFIED'?'selected':''}>${label}</option>`).join('')}</select></label><label>중요도<select name="importance">${[[2,'보통'],[3,'높음'],[1,'낮음']].map(([v,l])=>`<option value="${v}" ${(draft.importance||2)===v?'selected':''}>${l}</option>`).join('')}</select></label></div><details class="thesis-form-extra" ${editing?'open':''}><summary>중요하게 확인할 것 · 재검토 조건</summary><label>중요하게 확인할 것<textarea name="monitoringTopics" rows="3" maxlength="2400" placeholder="한 줄에 하나씩 입력하세요">${esc(array(draft.monitoringTopics).join('\n'))}</textarea></label><label>생각을 다시 검토할 조건<textarea name="reconsiderationConditions" rows="3" maxlength="2400" placeholder="예: 관련 사업 수주가 두 분기 연속 감소하면 재검토">${esc(array(draft.reconsiderationConditions).join('\n'))}</textarea></label><label>연결 산업·주제<input name="linkedIndustryConcepts" maxlength="500" value="${esc(array(draft.linkedIndustryConcepts).join(', '))}" placeholder="쉼표로 구분"></label></details>${editing?'<label>변경 이유<input name="changeReason" maxlength="500" placeholder="어떤 점을 바꿨는지 적어 주세요" required></label>':''}<p class="thesis-muted">저장하는 내용은 나의 생각입니다. 검토 결과가 저장된 생각을 자동으로 바꾸지는 않습니다.</p><div class="thesis-actions"><button type="submit" class="primary-button">${editing?'새 버전 저장':'확인하고 저장'}</button><a href="${editing?url(draft.id):'/catalyst'+(draft.sourceChatId?'?chat='+encodeURIComponent(draft.sourceChatId):'')}" data-nav>취소</a></div></form></section>`;
}
function assetHref(a){return a.kind==='KR_STOCK'||a.market==='KR'?'/stock/KR/'+encodeURIComponent(a.symbol||a.ticker):a.kind==='US_STOCK'||a.market==='US'?'/stock/US/'+encodeURIComponent(a.symbol||a.ticker):null;}
function detailMarkup(d){
 const reviews=array(d.reviews),versions=array(d.versions),activeReview=d.latestReview,archived=d.status==='ARCHIVED';
 return `<header class="thesis-heading"><div><a href="/catalyst?theses=1" data-nav>← 내 투자 생각</a><h1>${esc(d.title)}</h1><p class="thesis-muted">버전 ${esc(d.currentVersion)} · ${esc(positions[d.positionContext]||positions.UNSPECIFIED)}${archived?' · 보관됨':''}</p></div>${!archived?`<button class="primary-button" type="button" data-thesis-review="${esc(d.id)}" data-thesis-version="${esc(d.currentVersion)}" ${active(activeReview)?'disabled':''}>${active(activeReview)?'변화 확인 중…':'새 변화 확인'}</button>`:''}</header><section class="surface thesis-belief"><span class="thesis-badge">내가 저장한 생각</span><p>${esc(d.thesisText)}</p><div class="thesis-linked-assets">${array(d.linkedAssets).map(a=>assetHref(a)?`<a href="${assetHref(a)}?tab=company" data-nav>${esc(a.name)} · ${esc(a.symbol)}<small>사업·매출 구조 보기 →</small></a>`:`<span>${esc(a.name||a.symbol)}</span>`).join('')}</div>${d.baseline?.initialEvidenceStatus==='NOT_ESTABLISHED'?'<p class="thesis-muted">초기 근거 미확보 · 처음 확인한 자료는 변화와 구분합니다.</p>':''}${array(d.linkedIndustryConcepts).length?`<p class="thesis-muted">${esc(d.linkedIndustryConcepts.join(' · '))}</p>`:''}${array(d.monitoringTopics).length||array(d.reconsiderationConditions).length?`<details><summary>내 확인 항목과 재검토 조건</summary>${listMarkup('중요하게 확인할 것',d.monitoringTopics)}${listMarkup('생각을 다시 검토할 조건',d.reconsiderationConditions)}</details>`:''}<div class="thesis-actions">${!archived?'<button class="secondary-button" type="button" data-thesis-edit>내 생각 수정</button><button class="thesis-text-button" type="button" data-thesis-archive>추적 보관</button>':''}<small>저장 ${esc(time(d.createdAt))}</small></div><div class="thesis-archive-confirm" hidden><p>이 생각을 보관할까요? 생각과 검토 기록은 남고, 보유·관심 상태는 바뀌지 않습니다.</p><button class="secondary-button" type="button" data-thesis-archive-confirm>보관하기</button> <button class="thesis-text-button" type="button" data-thesis-archive-cancel>취소</button></div>${array(d.baseline?.evidence).length?`<details class="thesis-initial"><summary>저장 당시 주요 근거</summary><p class="thesis-muted">생각 저장 시점 ${esc(time(d.createdAt))} · 자료의 발행일과 기준기간은 아래 출처를 확인하세요.</p>${sourcesMarkup(d.baseline.evidence)}</details>`:''}</section><section class="surface thesis-current-result">${activeReview&&activeReview.thesisVersion!==d.currentVersion?'<p class="thesis-muted">아래는 수정 전 생각의 검토입니다. 현재 버전의 새 변화 확인은 아직 실행하지 않았습니다.</p>':''}${thesisReviewMarkup(activeReview)}</section><section class="surface thesis-followup"><h2>이 생각에서 이어서 질문</h2><form data-thesis-followup><label for="thesis-question">더 확인하고 싶은 점</label><textarea id="thesis-question" name="q" maxlength="900" rows="2" placeholder="기업 전체에서 이 사업 비중은 어느 정도야?" required></textarea><button type="submit" class="secondary-button">질문창으로 이동 →</button></form></section><details class="surface thesis-history"><summary>생각 변경 이력 ${versions.length}개</summary>${versions.map(v=>`<article><h3>버전 ${esc(v.version||v.thesisVersion)} · ${esc(v.title||d.title)}</h3><p>${esc(v.thesisText||v.thesis_text)}</p>${v.changeReason?`<p>변경 이유 · ${esc(v.changeReason)}</p>`:''}<small>${esc(time(v.createdAt||v.created_at))}</small></article>`).join('')}</details><details class="surface thesis-history"><summary>이전 검토 ${reviews.filter(r=>r.id!==activeReview?.id).length}개</summary>${reviews.filter(r=>r.id!==activeReview?.id).map(r=>`<details><summary>버전 ${esc(r.thesisVersion)} · ${esc(time(r.completedAt||r.createdAt))}</summary>${thesisReviewMarkup(r)}</details>`).join('')||'<p>이전 검토가 없습니다.</p>'}</details>`;
}
export function mountTheses(root){
 const controller=new AbortController(),api=client(controller.signal);let data=null,draft=null,selected=new Map(),known=new Map(),timer,searchTimer,editing=false,searchVersion=0,saving=false;
 const p=new URLSearchParams(location.search),id=p.get('thesis'),chat=p.get('thesisDraft');
 root.innerHTML='<div class="thesis-shell"><p class="thesis-error" role="alert" hidden></p><div class="thesis-content"><p role="status">내 투자 생각을 불러오는 중입니다.</p></div></div>';
 const content=root.querySelector('.thesis-content'),error=root.querySelector('.thesis-error'),fail=e=>{if(controller.signal.aborted)return;error.hidden=false;error.textContent=e.message;error.scrollIntoView({block:'nearest'});};
 const go=href=>{window.history.pushState(null,'',href);window.dispatchEvent(new PopStateEvent('popstate'));};
 function selectedMarkup(){const box=root.querySelector('[data-thesis-selected]');if(!box)return;box.innerHTML=[...selected.values()].map(a=>`<span class="thesis-asset-chip">${esc(a.name||a.symbol)} · ${esc(a.symbol||'')}<button type="button" data-thesis-asset-remove="${esc(a.id)}" aria-label="${esc(a.name||a.symbol)} 연결 해제">×</button></span>`).join('')||'<p class="thesis-muted">선택한 종목 없음</p>';}
 function optionsMarkup(items){for(const a of items)known.set(a.id,a);root.querySelector('[data-thesis-asset-options]').innerHTML=items.map(a=>`<button type="button" class="thesis-asset-option" data-thesis-asset-add="${esc(a.id)}">${esc(a.name)} · ${esc(a.symbol)} <small>${esc(({KR_STOCK:'국내 주식',US_STOCK:'미국 주식',CRYPTO:'가상화폐'})[a.kind]||a.market||'')} · 선택</small></button>`).join('');}
 function form(d,isEdit){draft=d;editing=isEdit;selected=new Map(array(d.linkedAssets).filter(a=>array(d.linkedAssetIds).includes(a.id)).map(a=>[a.id,a]));for(const assetId of array(d.linkedAssetIds))if(!selected.has(assetId))selected.set(assetId,array(d.assetSuggestions).find(a=>a.id===assetId)||{id:assetId,name:assetId});known=new Map(selected);content.innerHTML=thesisEditMarkup(d,isEdit);selectedMarkup();optionsMarkup(array(d.assetSuggestions).filter(a=>!selected.has(a.id)));}
 async function load(){try{if(chat){const d=await api('/draft?chat='+encodeURIComponent(chat));if(controller.signal.aborted)return;form(d,false);}else if(id){data=await api('/'+encodeURIComponent(id));if(controller.signal.aborted)return;content.innerHTML=detailMarkup(data);if(active(data.latestReview))poll(data.id,data.latestReview.id);}else{const filter=['ACTIVE','ARCHIVED','ALL'].includes(p.get('status'))?p.get('status'):'ACTIVE',list=await api('?status='+filter);if(controller.signal.aborted)return;content.innerHTML=`<header class="thesis-heading"><div><span class="eyebrow">MY INVESTMENT THESIS</span><h1>내 투자 생각</h1><p class="thesis-muted">저장한 생각과 새 근거를 직접 비교해 보세요.</p></div><a class="secondary-button" href="/catalyst" data-nav>자유롭게 질문하기 →</a></header><nav class="thesis-filter" aria-label="투자 생각 상태">${[['ACTIVE','추적 중'],['ARCHIVED','보관함'],['ALL','전체']].map(([key,label])=>`<a href="/catalyst?theses=1&status=${key}" data-nav ${filter===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="thesis-list">${list.items.length?list.items.map(x=>thesisCardMarkup(x)).join(''):'<section class="surface thesis-empty"><h2>생각을 남겨 보세요</h2><p>분석 답변에서 ‘이 생각 계속 추적’을 눌러 시작하세요.</p><a href="/catalyst" data-nav>투자 리서치로 이동 →</a></section>'}</div>`;}}catch(e){fail(e);content.innerHTML='<button class="secondary-button" type="button" data-thesis-retry>다시 불러오기</button>';}}
 async function poll(thesisId,reviewId){clearTimeout(timer);try{const r=await api('/'+encodeURIComponent(thesisId)+'/reviews/'+encodeURIComponent(reviewId));if(controller.signal.aborted)return;if(active(r)){timer=setTimeout(()=>poll(thesisId,reviewId),2500);return;}await load();}catch(e){fail(e);}}
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-thesis-retry')){error.hidden=true;void load();}
  if(b.hasAttribute('data-thesis-edit'))form(data,true);
  if(b.hasAttribute('data-thesis-archive'))root.querySelector('.thesis-archive-confirm').hidden=false;
  if(b.hasAttribute('data-thesis-archive-cancel'))root.querySelector('.thesis-archive-confirm').hidden=true;
  if(b.hasAttribute('data-thesis-archive-confirm')){b.disabled=true;try{await api('/'+encodeURIComponent(data.id)+'/archive',{method:'POST',body:JSON.stringify({expectedVersion:data.currentVersion})});await load();}catch(e){fail(e);b.disabled=false;}}
  if(b.dataset.thesisAssetAdd){const a=known.get(b.dataset.thesisAssetAdd);if(a){selected.set(a.id,a);selectedMarkup();b.remove();}}
  if(b.dataset.thesisAssetRemove){selected.delete(b.dataset.thesisAssetRemove);selectedMarkup();}
  if(b.dataset.thesisReview){b.disabled=true;error.hidden=true;try{const r=await api('/'+encodeURIComponent(b.dataset.thesisReview)+'/review',{method:'POST',body:JSON.stringify({expectedVersion:Number(b.dataset.thesisVersion)})});if(!id){go(url(b.dataset.thesisReview));return;}await load();if(active(r))poll(id,r.id);}catch(e){fail(e);b.disabled=false;}}
 },{signal:controller.signal});
 root.addEventListener('input',e=>{if(!e.target.matches('[data-thesis-asset-search]'))return;clearTimeout(searchTimer);const query=e.target.value.trim(),version=++searchVersion;if(query.length<2){optionsMarkup([]);return;}searchTimer=setTimeout(async()=>{try{const r=await fetch('/api/catalyst/assets?q='+encodeURIComponent(query),{headers:headers(),signal:controller.signal}),d=await r.json();if(!r.ok)throw Error('종목 검색에 실패했습니다.');if(controller.signal.aborted||version!==searchVersion)return;optionsMarkup(array(d.items).filter(a=>!selected.has(a.id)));}catch(e){fail(e);}},300);},{signal:controller.signal});
 root.addEventListener('submit',async e=>{const formEl=e.target;e.preventDefault();if(formEl.matches('[data-thesis-followup]')){go('/catalyst?'+new URLSearchParams({thesisContext:data.id,q:formEl.elements.q.value.trim()}));return;}if(!formEl.matches('[data-thesis-form]')||saving)return;saving=true;const submit=formEl.querySelector('[type=submit]');submit.disabled=true;error.hidden=true;const values=new FormData(formEl),lines=name=>String(values.get(name)||'').split('\n').map(x=>x.trim()).filter(Boolean),body={title:String(values.get('title')).trim(),thesisText:String(values.get('thesisText')).trim(),linkedAssetIds:[...selected.keys()],positionContext:values.get('positionContext'),importance:Number(values.get('importance')),monitoringTopics:lines('monitoringTopics'),reconsiderationConditions:lines('reconsiderationConditions'),linkedIndustryConcepts:String(values.get('linkedIndustryConcepts')||'').split(',').map(x=>x.trim()).filter(Boolean),...(editing?{expectedVersion:draft.currentVersion,changeReason:String(values.get('changeReason')).trim()}:{sourceChatId:draft.sourceChatId})};try{const r=await api(editing?'/'+encodeURIComponent(draft.id):'',{method:editing?'PATCH':'POST',body:JSON.stringify(body)});if(!controller.signal.aborted)go(url(r.id||draft.id));}catch(e){fail(e);submit.disabled=false;}finally{saving=false;}},{signal:controller.signal});
 void load();return {destroy(){controller.abort();clearTimeout(timer);clearTimeout(searchTimer);}};
}
export function mountThesisHome(root){
 const controller=new AbortController(),api=client(controller.signal);root.innerHTML='<div class="thesis-home-heading"><h2>내 투자 생각에서 달라진 점</h2><a href="/catalyst?theses=1" data-nav>모두 보기 →</a></div><div class="thesis-home-body"><p class="thesis-muted" role="status">저장한 생각을 확인하고 있습니다.</p></div><p class="thesis-error" role="alert" hidden></p>';
 async function load(){try{const result=await api('/home');if(controller.signal.aborted)return;root.querySelector('.thesis-home-body').innerHTML=result.items.length?`<div class="thesis-home-grid">${result.items.map(x=>thesisCardMarkup(x,{home:true})).join('')}</div>`:'<p>분석 답변에서 ‘이 생각 계속 추적’을 눌러 시작하세요.</p><form class="thesis-home-question"><label class="sr-only" for="thesis-home-query">투자 리서치 질문</label><input id="thesis-home-query" name="q" maxlength="900" placeholder="어떤 투자 생각을 살펴볼까요?" required><button class="secondary-button" type="submit">질문창 열기 →</button></form>';}catch{if(!controller.signal.aborted)root.querySelector('.thesis-home-body').innerHTML='<p class="thesis-muted">내 투자 생각을 불러오지 못했습니다. <button class="thesis-text-button" data-thesis-home-retry>다시 확인</button></p>';}}
 root.addEventListener('submit',e=>{if(!e.target.matches('.thesis-home-question'))return;e.preventDefault();window.history.pushState(null,'','/catalyst?q='+encodeURIComponent(e.target.elements.q.value.trim()));window.dispatchEvent(new PopStateEvent('popstate'));},{signal:controller.signal});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-thesis-review]');if(e.target.closest('[data-thesis-home-retry]'))void load();if(!b)return;b.disabled=true;try{await api('/'+encodeURIComponent(b.dataset.thesisReview)+'/review',{method:'POST',body:JSON.stringify({expectedVersion:Number(b.dataset.thesisVersion)})});window.history.pushState(null,'',url(b.dataset.thesisReview));window.dispatchEvent(new PopStateEvent('popstate'));}catch(err){if(controller.signal.aborted)return;const notice=root.querySelector('.thesis-error');notice.hidden=false;notice.textContent=err.message;b.disabled=false;}},{signal:controller.signal});
 void load();return {destroy(){controller.abort();}};
}
